// rename-colors.js — use_figma script: rename COLOR variables by ID (naming only). Generated by make-rename-payloads.mjs.
// Changes ONLY variable.name. IDs, keys, values, modes, aliases, scopes, codeSyntax, styles and bindings are untouched
// (bindings and aliases reference variable IDs, not names).
// Preflight is all-or-nothing: if any row fails, nothing is written. If a write throws mid-way, the applied rows are reverted.
// direction "forward" renames old → new; "rollback" renames new → old using the same rows.
const CONFIG = { fileKey: "__FILEKEY__", batch: "__BATCH__", direction: "__DIRECTION__" };
const ROWS = __ROWS__;   // [id, old, new]
if (figma.fileKey !== CONFIG.fileKey) throw new Error("wrong file " + figma.fileKey);
const fwd = CONFIG.direction === "forward";
const all = await figma.variables.getLocalVariablesAsync();
const byId = new Map(all.map((v) => [v.id.replace(/^VariableID:/, ""), v]));
const taken = new Map(all.map((v) => [v.variableCollectionId + "|" + v.name, v.id.replace(/^VariableID:/, "")]));
const moving = new Set(ROWS.map((r) => r[0]));
const errors = [], plan = [];
for (const [id, oldName, newName] of ROWS) {
  const from = fwd ? oldName : newName, to = fwd ? newName : oldName, v = byId.get(id);
  if (!v) { errors.push(`missing ${id}`); continue; }
  if (v.resolvedType !== "COLOR") errors.push(`${id} not COLOR`);
  if (v.remote) errors.push(`${id} is remote`);
  if (v.name !== from) { errors.push(`${id} name is "${v.name}", expected "${from}"`); continue; }
  const occ = taken.get(v.variableCollectionId + "|" + to);
  if (occ && occ !== id && !moving.has(occ)) errors.push(`${id} target "${to}" is taken by ${occ}`);
  plan.push([v, from, to]);
}
if (errors.length) return { ok: false, batch: CONFIG.batch, direction: CONFIG.direction, written: 0, errors: errors.slice(0, 50), errorCount: errors.length };
const done = [];
try { for (const [v, from, to] of plan) { v.name = to; done.push([v, from]); } }
catch (e) { for (const [v, from] of done.reverse()) v.name = from; return { ok: false, reverted: done.length, error: String(e) }; }
// read-back by ID
const after = await figma.variables.getLocalVariablesAsync();
const now = new Map(after.map((v) => [v.id.replace(/^VariableID:/, ""), v.name]));
const wrong = plan.filter(([v, , to]) => now.get(v.id.replace(/^VariableID:/, "")) !== to).length;
const dup = after.length - new Set(after.map((v) => v.variableCollectionId + "|" + v.name)).size;
return { ok: wrong === 0 && dup === 0, batch: CONFIG.batch, direction: CONFIG.direction, written: done.length, readBackMismatches: wrong, duplicateNames: dup, variables: after.length };
